    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🔥", "👀"];

    private List<Channel>? _channels;
    private int? _activeChannelId;
    private Channel? _activeChannel;
    private List<Message>? _messages;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();
    private int _skip;
    private bool _loadingMore;
    private bool _allLoaded;

    private string _newMessageText = "";
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    // Thread panel state
    private bool _threadOpen;
    private int? _threadRootId;
    private Message? _threadRootMessage;
    private List<Message>? _threadReplies;
    private string _threadReplyText = "";

    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == _activeChannelId) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _skip = 0;
        _allLoaded = false;
        _messages = null;
        _threadSummaries.Clear();
        CloseThread();

        var messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = messages;
        _skip = messages.Count;

        await BuildThreadSummariesAsync();
        await ChatService.MarkChannelReadAsync(channel.Id);
        await RefreshChannelUnread(channel.Id);
    }

    private async Task RefreshChannelUnread(int channelId)
    {
        var refreshed = await ChatService.GetChannelsAsync();
        if (_channels is not null && refreshed is not null)
        {
            _channels = refreshed;
        }
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_activeChannelId is null || _loadingMore || _allLoaded) return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _skip, PageSize);
        if (older.Count == 0)
        {
            _allLoaded = true;
        }
        else
        {
            _messages = [..older, ..(_messages ?? [])];
            _skip += older.Count;
            await BuildThreadSummariesAsync();
        }

        _loadingMore = false;
    }

    private async Task OnMessageScroll()
    {
        // Trigger load-more when user scrolls near the top
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await LoadOlderMessagesAsync();
        }
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageText.Trim(), null);
        _messages ??= [];
        _messages.Add(msg);
        _skip++;
        _newMessageText = "";

        await ScrollToBottomAsync();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh messages to show the updated reaction
        if (_activeChannelId is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _skip);
            _messages = refreshed;
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    // ── Thread operations ──

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadReplyText = "";
        _threadOpen = true;
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootId = null;
        _threadRootMessage = null;
        _threadReplies = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _activeChannelId is null || _threadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootId);
        _threadReplies ??= [];
        _threadReplies.Add(reply);
        _threadReplyText = "";

        await BuildThreadSummariesAsync();
    }

    // ── Thread summaries ──

    private async Task BuildThreadSummariesAsync()
    {
        if (_messages is null) return;

        _threadSummaries.Clear();

        // Identify root messages (messages with no ReplyToId that have replies referencing them)
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var rootId in rootIds)
        {
            try
            {
                var thread = await ChatService.GetThreadAsync(rootId);
                if (thread.Count > 0)
                {
                    _threadSummaries[rootId] = new ThreadSummary(
                        rootId,
                        thread.Count,
                        thread.Max(t => t.SentAt)
                    );
                }
            }
            catch
            {
                // Thread may not exist yet; ignore
            }
        }
    }

    private ThreadSummary? GetThreadSummary(int messageId)
    {
        return _threadSummaries.GetValueOrDefault(messageId);
    }

    // ── Helpers ──

    private async Task ScrollToBottomAsync()
    {
        await JS.InvokeVoidAsync("eval",
            "let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string Truncate(string text, int maxLen)
    {
        return text.Length <= maxLen ? text : string.Concat(text.AsSpan(0, maxLen), "…");
    }
}
