@page "/chat"
@layout ChatLayout
@using sv_6d536559400749feb851fa533ebc8b4f.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    @* ───── Left Sidebar ───── *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h4>Channels</h4>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var ch in _channels)
                {
                    <li class="channel-item @(ch.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(ch)">
                        <div class="channel-name"># @ch.Name</div>
                        <div class="channel-desc">@Truncate(ch.Description, 40)</div>
                        @if (ch.UnreadCount > 0)
                        {
                            <span class="unread-badge">@ch.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ───── Main Message Area ───── *@
    <section class="message-area @(_threadOpen ? "thread-open" : "")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h5># @_activeChannel.Name</h5>
                <span class="channel-description">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageScroll">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-bubble">
                                <div class="message-meta">
                                    <span class="author">@msg.Author</span>
                                    <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="message-content">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var r in msg.Reactions)
                                        {
                                            <span class="reaction-badge" title="@string.Join(", ", r.Users)">
                                                @r.Emoji @r.Users.Count
                                            </span>
                                        }
                                    </div>
                                }

                                @{ var summary = GetThreadSummary(msg.Id); }
                                @if (summary is not null)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)"
                                            @onclick:stopPropagation="true">
                                        @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                    </button>
                                }
                            </div>

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg.Id)">💬 Reply</button>
                                    <div class="emoji-picker-wrapper">
                                        <button class="action-btn" title="Add reaction"
                                                @onclick="() => ToggleEmojiPicker(msg.Id)">😊 React</button>
                                        @if (_emojiPickerMessageId == msg.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in _commonEmojis)
                                                {
                                                    <button class="emoji-option"
                                                            @onclick="() => AddReactionAsync(msg.Id, emoji)">@emoji</button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-input" rows="2"
                          placeholder="Message #@_activeChannel.Name"
                          @bind="_newMessageText"
                          @onkeydown="OnMessageKeyDown" />
                <button class="send-btn" @onclick="SendMessageAsync"
                        disabled="@string.IsNullOrWhiteSpace(_newMessageText)">Send</button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ───── Right Thread Panel ───── *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h5>Thread</h5>
                <button class="close-thread-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>

            <div class="thread-root-quote">
                <div class="message-meta">
                    <span class="author">@_threadRootMessage.Author</span>
                    <span class="timestamp">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                </div>
                <div class="message-content">@_threadRootMessage.Content</div>
            </div>

            <div class="thread-replies">
                @if (_threadReplies is not null)
                {
                    @foreach (var reply in _threadReplies)
                    {
                        <div class="message-row">
                            <div class="message-bubble">
                                <div class="message-meta">
                                    <span class="author">@reply.Author</span>
                                    <span class="timestamp">@FormatRelativeTime(reply.SentAt)</span>
                                </div>
                                <div class="message-content">@reply.Content</div>
                                @if (reply.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var r in reply.Reactions)
                                        {
                                            <span class="reaction-badge" title="@string.Join(", ", r.Users)">
                                                @r.Emoji @r.Users.Count
                                            </span>
                                        }
                                    </div>
                                }
                            </div>
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-input" rows="2"
                          placeholder="Reply in thread…"
                          @bind="_threadReplyText"
                          @onkeydown="OnThreadKeyDown" />
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">Reply</button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🔥", "👀"];

    private List<Channel>? _channels;
    private int? _activeChannelId;
    private Channel? _activeChannel;
    private List<Message>? _messages;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();
    private int _skip;
    private bool _loadingMore;
    private bool _allLoaded;

    private string _newMessageText = "";
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    // Thread panel state
    private bool _threadOpen;
    private int? _threadRootId;
    private Message? _threadRootMessage;
    private List<Message>? _threadReplies;
    private string _threadReplyText = "";

    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == _activeChannelId) return;

        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _skip = 0;
        _allLoaded = false;
        _messages = null;
        _threadSummaries.Clear();
        CloseThread();

        var messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = messages;
        _skip = messages.Count;

        await BuildThreadSummariesAsync();
        await ChatService.MarkChannelReadAsync(channel.Id);
        await RefreshChannelUnread(channel.Id);
    }

    private async Task RefreshChannelUnread(int channelId)
    {
        var refreshed = await ChatService.GetChannelsAsync();
        if (_channels is not null && refreshed is not null)
        {
            _channels = refreshed;
        }
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_activeChannelId is null || _loadingMore || _allLoaded) return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _skip, PageSize);
        if (older.Count == 0)
        {
            _allLoaded = true;
        }
        else
        {
            _messages = [..older, ..(_messages ?? [])];
            _skip += older.Count;
            await BuildThreadSummariesAsync();
        }

        _loadingMore = false;
    }

    private async Task OnMessageScroll()
    {
        // Trigger load-more when user scrolls near the top
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await LoadOlderMessagesAsync();
        }
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null) return;

        var msg = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageText.Trim(), null);
        _messages ??= [];
        _messages.Add(msg);
        _skip++;
        _newMessageText = "";

        await ScrollToBottomAsync();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh messages to show the updated reaction
        if (_activeChannelId is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _skip);
            _messages = refreshed;
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    // ── Thread operations ──

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages?.FirstOrDefault(m => m.Id == rootMessageId);
        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadReplyText = "";
        _threadOpen = true;
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootId = null;
        _threadRootMessage = null;
        _threadReplies = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _activeChannelId is null || _threadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootId);
        _threadReplies ??= [];
        _threadReplies.Add(reply);
        _threadReplyText = "";

        await BuildThreadSummariesAsync();
    }

    // ── Thread summaries ──

    private async Task BuildThreadSummariesAsync()
    {
        if (_messages is null) return;

        _threadSummaries.Clear();

        // Identify root messages (messages with no ReplyToId that have replies referencing them)
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var rootId in rootIds)
        {
            try
            {
                var thread = await ChatService.GetThreadAsync(rootId);
                if (thread.Count > 0)
                {
                    _threadSummaries[rootId] = new ThreadSummary(
                        rootId,
                        thread.Count,
                        thread.Max(t => t.SentAt)
                    );
                }
            }
            catch
            {
                // Thread may not exist yet; ignore
            }
        }
    }

    private ThreadSummary? GetThreadSummary(int messageId)
    {
        return _threadSummaries.GetValueOrDefault(messageId);
    }

    // ── Helpers ──

    private async Task ScrollToBottomAsync()
    {
        await JS.InvokeVoidAsync("eval",
            "let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string Truncate(string text, int maxLen)
    {
        return text.Length <= maxLen ? text : string.Concat(text.AsSpan(0, maxLen), "…");
    }
}

