+        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyText.Trim(), _threadRootId);
+        _threadReplies ??= [];
+        _threadReplies.Add(reply);
+        _threadReplyText = "";
+
+        await BuildThreadSummariesAsync();
+    }
+
+    // ── Thread summaries ──
+
+    private async Task BuildThreadSummariesAsync()
+    {
+        if (_messages is null) return;
+
+        _threadSummaries.Clear();
+
+        // Identify root messages (messages with no ReplyToId that have replies referencing them)
+        var rootIds = _messages
+            .Where(m => m.ReplyToId is null)
+            .Select(m => m.Id)
+            .ToHashSet();
+
+        foreach (var rootId in rootIds)
+        {
+            try
+            {
+                var thread = await ChatService.GetThreadAsync(rootId);
+                if (thread.Count > 0)
+                {
+                    _threadSummaries[rootId] = new ThreadSummary(
+                        rootId,
+                        thread.Count,
+                        thread.Max(t => t.SentAt)
+                    );
+                }
+            }
+            catch
+            {
+                // Thread may not exist yet; ignore
+            }
+        }
+    }
+
+    private ThreadSummary? GetThreadSummary(int messageId)
+    {
+        return _threadSummaries.GetValueOrDefault(messageId);
+    }
+
+    // ── Helpers ──
+
+    private async Task ScrollToBottomAsync()
+    {
+        await JS.InvokeVoidAsync("eval",
+            "let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
+    }
+
+    private static string FormatRelativeTime(DateTime sentAt)
+    {
+        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
+
+        return diff.TotalSeconds switch
+        {
+            < 60 => "just now",
+            < 3600 => $"{(int)diff.TotalMinutes} min ago",
+            < 86400 => $"{(int)diff.TotalHours}h ago",
+            < 604800 => $"{(int)diff.TotalDays}d ago",
+            _ => sentAt.ToString("MMM d, yyyy")
+        };
+    }
+
+    private static string Truncate(string text, int maxLen)
+    {
+        return text.Length <= maxLen ? text : string.Concat(text.AsSpan(0, maxLen), "…");
+    }
+}
